// 2.2 — Function node: базовая логика на JavaScript.
// На вход приходит что угодно: число, строка или объект.
// На выход уходит объект с полем payload.

const input = msg.payload;
let inputType = typeof input;
let values = [];

if (Array.isArray(input)) {
    inputType = "array";
    values = input.slice();                       // массив
} else if (input !== null && typeof input === "object") {
    inputType = "object";
    values = Array.isArray(input.scores) ? input.scores.slice() : [];
} else if (typeof input === "number") {
    inputType = "number";
    for (let i = 1; i <= input; i++) {            // цикл for
        values.push(i);
    }
} else {
    inputType = "string";
    values = String(input).split(/\s+/).filter(Boolean).map(function (w) { return w.length; });
}

let sum = 0;
for (let i = 0; i < values.length; i++) {
    sum += values[i];
}
const count = values.length;
const avg = count > 0 ? sum / count : 0;

let verdict = "";
if (count === 0) {                                // if / else
    verdict = "нет данных для расчёта";
} else if (avg >= 4) {
    verdict = "средний балл высокий";
} else {
    verdict = "средний балл низкий";
}

msg.topic = "lab2/krupa-ii241/function";
msg.student = "Крупа Ксения (ИИ-241)";
msg.payload = {                                   // объект
    student: msg.student,
    inputType: inputType,
    values: values,
    count: count,
    sum: sum,
    avg: Number(avg.toFixed(2)),
    verdict: verdict
};

return msg;
